DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 067", "old_status": "missing_stimulus", "status": "ready", "question_id": "1fc8e885-cf7d-5f3f-be14-dc30fd43082a", "stem": "Use the three graphs shown to find f(−1) + g(−1) + h(−1).", "choices": [{"key": "A", "text": "−4"}, {"key": "B", "text": "−5"}, {"key": "C", "text": "−6"}, {"key": "D", "text": "−7"}], "type": "mcq", "correct": "B", "explanation": "At x = −1, the solid parabola gives f(−1) = −1, the dotted curve gives g(−1) = −2, and the dashed line gives h(−1) = −2. Their sum is −1 − 2 − 2 = −5.", "topic": "Functions, Transformations & Graphs", "note": "Rejoined PSD 067 page 199 to its three-function graph following PSD 066 on page 198.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 199, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 198, "rect": [52, 375, 440, 710]}}, {"id": "clean:GTC 043", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "b0663013-ddca-521f-81e0-0869dc5a57e0", "stem": "In the figure, A, B, and D lie on one straight line, with B between A and D. Triangle BDC is right-angled at D, angle CBD = 40°, angle CAB = 35°, and AC = 10 cm. What is AB, to the nearest hundredth of a centimeter?", "choices": [{"key": "A", "text": "1.36 cm"}, {"key": "B", "text": "5.74 cm"}, {"key": "C", "text": "6.84 cm"}, {"key": "D", "text": "8.19 cm"}], "type": "mcq", "correct": "A", "explanation": "In triangle ABC, angle ABC = 180° − 40° = 140° and angle ACB = 180° − 35° − 140° = 5°. By the sine rule, AB/sin(5°) = 10/sin(140°). Thus AB ≈ 1.355886 cm, which rounds to 1.36 cm.", "topic": "Triangles, Trigonometry & Similarity", "note": "Recovered its diagram from HOA 111 page 69 and checked all given angles and options on page 396.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 396, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 69, "rect": [167, 280, 510, 600]}}, {"id": "est2-papers-2026-09-26:l1dec:q20", "old_status": "needs_source_repair", "status": "ready", "question_id": "f9b3d45a-9b2b-5925-b1c8-2c4a1e2acfd3", "stem": "A nonhorizontal, nonvertical line passes through three distinct points \\((a,b),(c,d),(e,f)\\). Which relation is NOT correct?", "choices": [{"key": "A", "text": "\\(\\frac{c-a}{d-b}=\\frac{c-e}{d-f}\\)"}, {"key": "B", "text": "\\(\\frac{d-b}{d-f}\\frac{c-e}{a-c}=1\\)"}, {"key": "C", "text": "\\(\\frac{d-b}{d-f}\\frac{c-e}{c-a}=1\\)"}, {"key": "D", "text": "\\(\\frac{c-a}{d-b}+\\frac{c-e}{f-d}=0\\)"}, {"key": "E", "text": "\\(\\frac{d-b}{d-f}-\\frac{c-a}{c-e}=0\\)"}], "type": "mcq", "correct": "B", "explanation": "Let the nonzero slope be s. Then d−b=s(c−a) and d−f=s(c−e). In C, the product is 1 after cancellation; B replaces c−a with its negative a−c, so its product is −1, not 1. The same two slope equalities verify A, D, and E. Distinct points on a nonhorizontal, nonvertical line make every displayed denominator nonzero.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Editorial clarification excludes horizontal and vertical lines so every expression is defined.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 6}, {"id": "est2-papers-2026-09-26:l1dec:q42", "old_status": "needs_source_repair", "status": "ready", "question_id": "d010ff98-e902-5a48-968a-d5561b69b577", "stem": "Let m and n be the roots (real or complex) of \\(ax^2+bx+c=0\\), where a, b, and c are nonzero real numbers. Hold b and c fixed while varying nonzero a. Which quantities remain constant? I. mn; II. m+n; III. 1/m+1/n.", "choices": [{"key": "A", "text": "Only I"}, {"key": "B", "text": "Only II"}, {"key": "C", "text": "Only III"}, {"key": "D", "text": "I and II"}, {"key": "E", "text": "I, II, and III"}], "type": "mcq", "correct": "C", "explanation": "Vieta’s formulas give mn=c/a and m+n=−b/a. Because b and c are nonzero, both depend on a. Since neither root is zero, 1/m+1/n=(m+n)/(mn)=−b/c, which is independent of a. Only III remains constant.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Editorial clarification: all three coefficients nonzero. The previous review note missed b=0, which would also make II constant.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 12}, {"id": "est2-papers-2026-09-26:l1dec:q44", "old_status": "needs_source_repair", "status": "ready", "question_id": "a663a028-065c-501a-b0d8-6ec959b2d84f", "stem": "Three circles of radii 1, 2, and 3 are pairwise externally tangent. What type of triangle is formed by joining their centers?", "choices": [{"key": "A", "text": "Isosceles"}, {"key": "B", "text": "Right angled"}, {"key": "C", "text": "Right isosceles"}, {"key": "D", "text": "Equilateral"}, {"key": "E", "text": "Cannot be determined"}], "type": "mcq", "correct": "B", "explanation": "External tangency makes the center distances the sums of the corresponding radii: 1+2=3, 1+3=4, and 2+3=5. Since 3²+4²=5², the triangle is right angled. Its unequal side lengths exclude the isosceles choices.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Editorial clarification specifies external tangency.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 13}, {"id": "est2-papers-2026-09-26:l1dec:q45", "old_status": "needs_source_repair", "status": "ready", "question_id": "30b154fb-685f-5899-8c46-390928fb405c", "stem": "For days d = 1, 2, 3, 4, 5, 6, 7, 8, the recorded numbers of cases are respectively 100, 350, 250, 600, 723, 702, 750, 790. Day 1 is October 19. Fit an ordinary least-squares line predicting cases from d. What is the first whole date on which its prediction is at least 1,000?", "choices": [{"key": "A", "text": "October 20"}, {"key": "B", "text": "October 23"}, {"key": "C", "text": "October 28"}, {"key": "D", "text": "October 31"}, {"key": "E", "text": "November 1"}], "type": "mcq", "correct": "C", "explanation": "The fitted slope is Σ(d−4.5)(N−533.125)/Σ(d−4.5)² = 98.9166667 and the intercept is 88. The prediction reaches 1,000 at d=(1000−88)/98.9166667≈9.2199. It is 978.25 on day 9 and 1077.1667 on day 10, so the first whole day is day 10, October 28.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected choice C from October 29 to October 28 and specified the first whole date at or above the threshold.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 13}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
